package com.qinghe.life.controller;
import com.qinghe.life.annotation.OperateLog; import com.qinghe.life.common.*; import com.qinghe.life.dto.*; import com.qinghe.life.service.AdminGoodsService; import com.qinghe.life.vo.AdminGoodsVO; import javax.validation.Valid; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/admin/goods") public class AdminGoodsController { private final AdminGoodsService service; public AdminGoodsController(AdminGoodsService service){this.service=service;} @GetMapping public Result<PageResult<AdminGoodsVO>> page(@Valid AdminGoodsQuery q){return Result.success(service.page(q));} @GetMapping("/{id}") public Result<AdminGoodsVO> detail(@PathVariable Long id){return Result.success(service.detail(id));} @PostMapping @OperateLog(module="商品管理",action="新增商品") public Result<AdminGoodsVO> create(@Valid @RequestBody AdminGoodsSaveRequest r){return Result.success(service.create(r));} @PutMapping("/{id}") @OperateLog(module="商品管理",action="修改商品资料") public Result<AdminGoodsVO> update(@PathVariable Long id,@Valid @RequestBody AdminGoodsSaveRequest r){return Result.success(service.update(id,r));} @PutMapping("/{id}/status") @OperateLog(module="商品管理",action="调整商品状态") public Result<Void> status(@PathVariable Long id,@Valid @RequestBody GoodsStatusRequest r){service.status(id,r);return Result.success();} @PutMapping("/{id}/stock") @OperateLog(module="商品管理",action="调整商品库存") public Result<Void> stock(@PathVariable Long id,@Valid @RequestBody GoodsStockRequest r){service.stock(id,r);return Result.success();} @PostMapping(value="/{id}/image",consumes="multipart/form-data") @OperateLog(module="商品管理",action="上传商品主图") public Result<AdminGoodsVO> image(@PathVariable Long id,@RequestParam("file") MultipartFile f){return Result.success(service.image(id,f));}}
